    "explanation": "Cây trồng chỉ có khả năng hấp thụ một lượng dinh dưỡng nhất định trong một khoảng thời gian nhất định, phù hợp với nhu cầu sinh trưởng thực tế của chúng; nếu bón phân đạm với liều lượng vượt quá nhiều so với nhu cầu thực tế của cây trồng, phần lượng đạm dư thừa mà cây không kịp hấp thụ hết sẽ tồn tại trong đất, và có nguy cơ bị rửa trôi theo nước mưa hoặc nước tưới, ngấm sâu xuống nguồn nước ngầm hoặc theo dòng chảy bề mặt đổ vào các sông, hồ, kênh, rạch lân cận; lượng đạm dư thừa này khi tích tụ trong nguồn nước có thể gây ra hiện tượng ô nhiễm nguồn nước, điển hình là hiện tượng phú dưỡng (eutrophication) - tình trạng dư thừa dinh dưỡng trong nước tạo điều kiện thuận lợi cho tảo và một số loại thực vật thuỷ sinh phát triển bùng nổ quá mức, gây ra các hậu quả tiêu cực như làm giảm lượng oxygen hoà tan trong nước (do tảo chết đi, phân huỷ tiêu tốn oxygen), gây hại nghiêm trọng đến các loài sinh vật thuỷ sinh khác và ảnh hưởng đến chất lượng nguồn nước sử dụng cho sinh hoạt của con người; vì những hậu quả môi trường tiềm ẩn này, việc bón phân đạm cần được tính toán, sử dụng đúng liều lượng cần thiết, tránh lãng phí và gây hại cho môi trường xung quanh."
