    "explanation": "Nguyên lí lực đẩy Ác-si-mét có phạm vi ứng dụng rộng rãi vì nó phản ánh một quy luật vật lí phổ quát, áp dụng cho bất kì vật thể nào được nhúng (một phần hay toàn bộ) trong bất kì loại chất lưu nào (chất lỏng hoặc chất khí), quy luật này đã được ứng dụng một cách thông minh, sáng tạo trong nhiều thiết kế kĩ thuật, công nghệ quan trọng: trong thiết kế tàu ngầm, con tàu có khả năng chủ động điều chỉnh việc lặn xuống hay nổi lên bằng cách bơm nước vào hoặc đẩy nước ra khỏi các khoang chứa đặc biệt (gọi là khoang dằn) bên trong thân tàu, việc thay đổi lượng nước này làm thay đổi trọng lượng tổng thể của tàu (trong khi thể tích tổng thể, và do đó lực đẩy Ác-si-mét tối đa có thể có, gần như không đổi), khi trọng lượng tàu tăng lên vượt quá lực đẩy Ác-si-mét, tàu sẽ lặn xuống, và ngược lại khi giảm trọng lượng, tàu sẽ nổi lên; trong thiết kế khinh khí cầu, khí cầu sử dụng một loại khí có khối lượng riêng nhỏ hơn không khí xung quanh (như khí helium, hoặc không khí được làm nóng để giảm khối lượng riêng) bơm vào một túi khí lớn, thể tích lớn của túi khí này khi ở trong không khí (một chất lưu, dù là chất khí) tạo ra một lực đẩy Ác-si-mét (trong không khí) đủ lớn để nâng toàn bộ khinh khí cầu (bao gồm cả khoang chở người, thiết bị) bay lên cao; trong thiết kế phao cứu sinh, phao thường được làm từ vật liệu nhẹ, có thể tích lớn (như xốp, hoặc chứa không khí bên trong), khi phao được đặt xuống nước cùng với người sử dụng, thể tích lớn của phao tạo ra lực đẩy Ác-si-mét đủ lớn để nâng đỡ, giữ cho cả phao và người sử dụng nổi trên mặt nước, không bị chìm; những ứng dụng đa dạng, quan trọng này minh chứng rõ ràng cho giá trị thực tiễn to lớn của việc hiểu và vận dụng nguyên lí lực đẩy Ác-si-mét, vượt xa phạm vi của các bài toán vật lí lí thuyết đơn giản trong sách giáo khoa."
