    "explanation": "Trong một ròng rọc cố định đơn lẻ, chỉ có một đoạn dây duy nhất chịu toàn bộ trọng lượng của vật cần nâng, do đó lực kéo mà người sử dụng cần tác dụng phải bằng đúng trọng lượng của vật (ròng rọc cố định chỉ thay đổi hướng của lực, không làm giảm độ lớn lực kéo); ngược lại, trong một hệ thống ròng rọc động (kết hợp nhiều ròng rọc, bao gồm ít nhất một ròng rọc di chuyển cùng với vật được nâng lên), trọng lượng của vật cần nâng được phân bổ, chia sẻ đồng đều cho nhiều đoạn dây khác nhau trong hệ thống (số lượng đoạn dây phụ thuộc vào số lượng ròng rọc động được sử dụng trong hệ thống), thay vì chỉ có một đoạn dây duy nhất phải chịu toàn bộ trọng lượng; vì trọng lượng được chia sẻ cho nhiều đoạn dây cùng chịu lực đồng thời, lực kéo cần thiết mà mỗi đoạn dây phải chịu (và tương ứng là lực mà người kéo cần tác dụng ở đầu dây) giảm xuống đáng kể so với trọng lượng thực tế của vật, tỉ lệ nghịch với số lượng đoạn dây cùng chịu lực trong hệ thống; đây chính là nguyên lí giúp hệ thống ròng rọc động có khả năng giảm đáng kể lực kéo cần thiết, mang lại lợi thế cơ học rõ rệt so với việc chỉ sử dụng ròng rọc cố định đơn lẻ."
