    "explanation": "Kéo cắt kim loại vận dụng nguyên lí đòn bẩy một cách rõ rệt trong thiết kế của nó: tay cầm của loại kéo này được thiết kế dài hơn đáng kể so với phần lưỡi cắt (ngắn hơn nhiều), với khớp nối (đóng vai trò điểm tựa) nằm giữa hai phần này; theo nguyên lí cân bằng mô men lực của đòn bẩy (F1×d1 = F2×d2), khi khoảng cách d1 (từ điểm đặt lực ở tay cầm đến điểm tựa) lớn hơn nhiều so với khoảng cách d2 (từ điểm tựa đến lưỡi cắt, nơi tác dụng lực lên kim loại), lực F2 tác dụng thực tế lên kim loại tại lưỡi cắt sẽ lớn hơn nhiều so với lực F1 mà tay người dùng cần tác dụng ở tay cầm; sự khuếch đại lực đáng kể này (nhờ tỉ lệ chênh lệch lớn giữa d1 và d2) cho phép người dùng chỉ cần dùng một lực tay tương đối vừa phải nhưng vẫn có thể tạo ra một lực cắt đủ lớn tại lưỡi kéo để xuyên qua các tấm kim loại tương đối dày, cứng - điều mà kéo cắt giấy thông thường (thường có tỉ lệ tay cầm/lưỡi cắt gần bằng nhau hơn, ít khuếch đại lực hơn) không thể thực hiện được hiệu quả."
