    "hint": "Cấu tạo bốn ngăn cho phép tách biệt hoàn toàn máu giàu oxygen và nghèo oxygen, tránh pha trộn không mong muốn; van tim đóng mở một chiều đảm bảo máu chỉ di chuyển theo một hướng, ngăn máu chảy ngược, đảm bảo hiệu quả bơm máu tối ưu.",
    "explanation": "Cấu tạo tim với bốn ngăn riêng biệt (hai tâm nhĩ, hai tâm thất) mang ý nghĩa sinh học quan trọng trong việc tối ưu hoá hiệu quả vận chuyển oxygen của hệ tuần hoàn: việc có bốn ngăn riêng biệt (thay vì một khoang chung duy nhất) cho phép tim tách biệt hoàn toàn hai dòng máu có tính chất khác nhau: dòng máu giàu oxygen (vừa được oxygen hoá tại phổi, cần được bơm đi nuôi khắp cơ thể) và dòng máu nghèo oxygen (đã cung cấp oxygen cho các tế bào, cần được bơm đến phổi để nhận thêm oxygen mới); nếu không có sự tách biệt rõ ràng này (như ở tim chỉ có một hoặc hai ngăn ở một số loài động vật kém tiến hoá hơn), hai dòng máu này có nguy cơ bị pha trộn với nhau, làm giảm đáng kể hiệu quả cung cấp oxygen cho cơ thể (vì máu được bơm đi nuôi cơ thể sẽ có nồng độ oxygen thấp hơn mức tối ưu do bị pha loãng bởi máu nghèo oxygen); bên cạnh đó, hệ thống van tim (nằm giữa các ngăn tim, và giữa tim với các mạch máu lớn) đóng vai trò quan trọng không kém, đảm bảo máu chỉ có thể di chuyển theo một chiều nhất định qua tim (từ tâm nhĩ xuống tâm thất, rồi từ tâm thất ra các động mạch lớn), ngăn ngừa hiện tượng máu chảy ngược trở lại ngăn trước đó khi tim co bóp, đây là yếu tố then chốt đảm bảo mỗi lần tim co bóp đều tạo ra một lực đẩy hiệu quả, đưa máu đi đúng hướng, tối đa hoá hiệu suất bơm máu của tim."
