    "hint": "Bụi mịn PM2.5 có kích thước cực nhỏ, vượt qua hàng rào bảo vệ tự nhiên của đường hô hấp trên để đi sâu vào phế nang, thậm chí xuyên qua thành phế nang vào máu; tích tụ theo thời gian gây viêm mạn tính, tổn thương phế nang, tăng nguy cơ bệnh hô hấp và tim mạch.",
